comms.text:
@1 וַהֲווֹ חַיֵּי שָׂרָה מְאָה וְעֶשְׂרִין וּשְׁבַע שְׁנִין שְׁנֵי חַיֵּי שָׂרָה:
@2 וּמִיתַת שָׂרָה בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן בְּאַרְעָא דִּכְנָעַן וַאֲתָא אַבְרָהָם לְמִסְפְּדָה לְשָׂרָה וּלְמִבְכַּהּ:
@3 וְקָם אַבְרָהָם מֵעַל אַפֵּי מִיתֵהּ וּמַלֵּל עִם בְּנֵי חִתָּאָה לְמֵימָר:
@4 דַּיָּר וְתוֹתַב אֲנָא עִמְּכוֹן הָבוּ לִי אַחֲסָנַת קְבוּרָא עִמְּכוֹן וְאִקְבַּר מִיתִי מִן קֳדָמָי:
@5 וַאֲתִיבוּ בְנֵי חִתָּאָה יָת אַבְרָהָם לְמֵימָר לֵהּ:
@6 קַבֵּל מִנָּנָא רִבּוֹנָנָא רַב קֳדָם יְיָ אַתְּ בֵּינָנָא בִּשְׁפַר קִבְרָנָא קְבַר יָת מִיתָךְ אֱנַשׁ מִנָּנָא יָת קִבְרֵהּ לָא יִמְנַע מִנָּךְ מִלְמִקְבַּר מִיתָךְ:
@7 וְקָם אַבְרָהָם וּסְגִיד לְעַמָּא דְאַרְעָא לִבְנֵי חִתָּאָה:
@8 וּמַלֵּל עִמְּהוֹן לְמֵימָר אִם אִית רַעֲוָא בְנַפְשְׁכוֹן לְמִקְבַּר יָת מִיתִי מִן קֳדָמַי קַבִּילוּ מִנִּי וּבְעוּ לִי מִן עֶפְרוֹן בַּר צוֹחַר:
@9 וְיִתֶּן לִי יָת מְעָרַת כָּפֶלְתָּא דִּי לֵהּ דִּי בִּסְטַר חַקְלֵהּ בְּכַסְפָּא שְׁלִים יִתְּנִינַהּ לִי בֵּינֵיכוֹן לְאַחֲסָנַת קְבוּרָא:
@10 וְעֶפְרוֹן יָתֵב בְּגוֹ בְּנֵי חִתָּאָה וְאָתֵיב עֶפְרוֹן חִתָּאָה יָת אַבְרָהָם קֳדָם בְּנֵי חִתָּאָה לְכֹל עָלֵי תְּרַע קַרְתֵּהּ לְמֵימָר:
@11 לָא רִבּוֹנִי קַבֵּיל מִנִּי חַקְלָא יְהָבִית לָךְ וּמְעַרְתָּא דִּי בֵהּ לָךְ יְהָבִיתַהּ לְעֵינֵי בְנֵי עַמִּי יְהָבִיתַהּ לָךְ קְבַר מִיתָךְ:
@12 וּסְגִיד אַבְרָהָם קֳדָם עַמָּא דְאַרְעָא:
@13 וּמַלֵּיל עִם עֶפְרוֹן קֳדָם עַמָּא דְאַרְעָא לְמֵימָר בְּרַם אִם אַתְּ עָבֵד לִי טִיבוּ קַבֵּל מִנִּי אֶתֵּן כַּסְפָּא דְמֵי חַקְלָא סַב מִנִּי וְאֶקְבַּר יָת מִיתִי תַּמָּן:
@14 וְאָתֵיב עֶפְרוֹן יָת אַבְרָהָם לְמֵימָר לֵהּ:
@15 רִבּוֹנִי קַבֵּל מִנִּי אַרְעָא שַׁוְיָא אַרְבַּע מְאָה סִלְעִין דִּכְסַף בֵּינָא וּבֵינָךְ מַה הִיא וְיָת מִיתָךְ קְבַר:
@16 וְקַבֵּל אַבְרָהָם מִן עֶפְרוֹן וּתְקַל אַבְרָהָם לְעֶפְרוֹן יָת כַּסְפָּא דְּמַלֵּיל קֳדָם בְּנֵי חִתָּאָה אַרְבַּע מְאָה סִלְעִין דִּכְסַף מִתְקַבֵּל סְחוֹרָא (נ''י דְּמִתְקַבֵּל סְחוֹרָתָא) בְּכָל מְדִינְתָּא:
@17 וְקָם חֲקַל עֶפְרוֹן דִּי בְּכָפֶלְתָּא דִּי קֳדָם מַמְרֵא חַקְלָא וּמְעַרְתָּא דִּי בֵהּ וְכָל אִילָנֵי דִּי בְחַקְלָא דִּי בְכָל תְּחוּמֵהּ סְחוֹר סְחוֹר:
@18 לְאַבְרָהָם לִזְבִינוֹהִי לְעֵינֵי בְּנֵי חִתָּאָה בְּכֹל עָלֵי תְּרַע קַרְתֵּהּ:
@19 וּבָתַר כֵּן קְבַר אַבְרָהָם יָת שָׂרָה אִתְּתֵהּ בִּמְעָרַת חֲקַל כָּפֶלְתָּא עַל אַפֵּי מַמְרֵא הִיא חֶבְרוֹן בְּאַרְעָא דִּכְנָעַן:
@20 וְקָם חַקְלָא וּמְעַרְתָּא דִּי בֵהּ לְאַבְרָהָם לְאַחֲסָנַת קְבוּרָא מִן בְּנֵי חִתָּאָה:
@21 וְאַבְרָהָם סִיב עָל בְּיוֹמִין וַיְיָ בְּרִיךְ יָת אַבְרָהָם בְּכֹלָא:
@22 וַאֲמַר אַבְרָהָם לְעַבְדֵהּ סָבָא דְבֵיתֵהּ דְּשַׁלִּיט בְּכָל דִי לֵהּ שַׁוִּי כְעַן יְדָךְ תְּחוֹת יַרְכִּי:
@23 וַאֲקַיֵּם עֲלָךְ בְּמֵימְרָא דַּיְיָ אֱלָהָא דִּשְׁמַיָּא וֵאלָהָא דְאַרְעָא דְּלָא תִסַּב אִתְּתָא לִבְרִי מִבְּנַת כְּנַעֲנָאֵי דִּי אֲנָא יָתֵב בֵּינֵיהוֹן:
@24 אֱלָהֵין לְאַרְעִי וּלְיַלָּדוּתִי תֵּיזִיל וְתִסַּב אִתְּתָא לִבְרִי לְיִצְחָק:
@25 וַאֲמַר לֵהּ עַבְדָא מָאִים לָא תֵיבֵי אִתְּתָא לְמֵיתֵי בַתְרַי לְאַרְעָא הָדָא הַאֲתָבָא אָתֵיב יָת בְּרָךְ לְאַרְעָא דִּי נְפַקְתָּא מִתַּמָּן:
@26 וַאֲמַר לֵהּ אַבְרָהָם אִסְתַּמַּר לָךְ דִּילְמָא תָתֵיב יָת בְּרִי לְתַמָּן:
@27 יְיָ אֱלָהָא דִּשְׁמַיָּא דִּי דַּבְּרַנִי מִבֵּית אַבָּא וּמֵאֲרַע יַלְדוּתִי וְדִי מַלֵּל לִי וְדִי קַיֵּם לִי לְמֵימַר לִבְרָךְ אֶתֵּן יָת אַרְעָא הָדָא הוּא יִשְׁלַח מַלְאָכֵהּ קֳדָמָךְ וְתִסַּב אִתְּתָא לִבְרִי מִתַּמָּן:
@28 וְאִם לָא תֵיבֵי אִתְּתָא לְמֵיתֵי בַתְרָךְ וּתְהֵי זַכָּאָה מִמּוֹמָתִי דָּא לְחוֹד יָת בְּרִי לָא תָתֵב לְתַמָּן:
@29 וְשַׁוִּי עַבְדָא יָת יְדֵהּ תְּחוֹת יַרְכָא דְאַבְרָהָם רִבּוֹנֵהּ וְקַיֵּם לֵהּ עַל פִּתְגָּמָא הָדֵין:
@30 וּדְבַר עַבְדָא עַשְׂרָא גַּמְלִין מִגַּמְלֵי רִבּוֹנֵהּ וַאֲזַל וְכָל שְׁפַר רִבּוֹנֵהּ בִּידֵהּ וְקָם וַאֲזַל לַאֲרָם דִּי עַל פְּרַת לְקַרְתָּא דְנָחוֹר:
@31 וְאַשְׁרֵי גַּמְלַיָּא מִבָּרָא לְקַרְתָּא לִבְאֵרָא דְמַיָּא לְעִדַּן רַמְשָׁא לְעִדַּן דְּנַפְקַן מַלְיָתָא:
@32 וַאֲמַר יְיָ אֱלָהֵהּ דְּרִבּוֹנִי אַבְרָהָם זַמִּין כְּעַן קֳדָמַי יוֹמָא דֵּין וְעִבַד טִיבוּ עִם רִבּוֹנִי אַבְרָהָם:
@33 הָא אֲנָא קָאֵם עַל עֵינָא דְמַיָּא וּבְנַת אֱנָשֵׁי קַרְתָּא נַפְקַן לְמִמְלֵי מַיָּא:
@34 וּתְהֵי עוּלֶמְתָּא דְּאֵימַר לַהּ אַרְכִינִי כְעַן קוּלְתִיךְ וְאֶשְׁתִּי וְתֵימַר אֵשְׁתְּ וְאַף גַּמְלָךְ אַשְׁקֵי יָתַהּ זַמִּנְתָּא לְעבְדָּךְ לְיִצְחָק וּבַהּ אִידַע אֲרֵי עֲבַדְתָּ טִיבוּ עִם רִבּוֹנִי:
@35 וַהֲוָה הוּא עַד לָא שֵׁיצֵי לְמַלָּלָא וְהָא רִבְקָה נְפָקַת דְּאִתְיְלִידַת לִבְתוּאֵל בַּר מִלְכָּה אִתַּת נָחוֹר אֲחוּהִי דְאַבְרָהָם וְקוּלְתַהּ עַל כַּתְפַּהּ:
@36 וְעוּלֶמְתָּא שַׁפִּירַת חֵיזוּ (נ''י שַׁפִּירָא לְמֶחֱזֵי) לַחֲדָא בְּתֻלְתָּא וּגְבַר לָא יַדְעָהּ וּנְחָתַת לְעֵינָא וּמְלַת קוּלְתַהּ וּסְלֵקָת:
@37 וּרְהַט עַבְדָּא לִקְדָמוּתַהּ וַאֲמַר אַשְׁקִינִי (נ''י אַטְעֵמְנִי) כְעַן זְעֵיר מַיָּא מִקּוּלְתִיךְ:
@38 וַאֲמֶרֶת אֵשְׁתְּ רִבּוֹנִי וְאוֹחִיאַת וַאֲחֵיתַת קוּלְתַהּ עַל יְדַהּ וְאַשְׁקְתֵהּ:
@39 וְשֵׁיצִיאַת לְאַשְׁקָיוּתֵהּ וַאֲמֶרֶת אַף לְגַמְלָךְ אַמְלֵי עַד דִּי סַפְקוּן לְמִשְׁתֵּי:
@40 וְאוֹחִיאַת וּנְפָצַת קוּלְתַהּ לְבֵית שַׁקְיָא וּרְהָטַת עוֹד לְבֵירָא לְמִמְלֵי וּמְלַת לְכָל גַּמְלוֹהִי:
@41 וְגַבְרָא שָׁהֵי בַהּ מִסְתַּכֵּל שָׁתִיק לְמֵידַע הַאַצְלַח יְיָ אָרְחֵהּ אִם לָא:
@42 וַהֲוָה כַּד סַפִּיקוּ גַּמְלַיָּא לְמִשְׁתֵּי וּנְסֵיב גַּבְרָא קָדָשָׁא דְדַהֲבָא תִּקְלָא מַתְקְלֵהּ וּתְרֵין שֵׁירִין עַל יְדָהָא מַתְקַל עֲשַׂר סִלְעִין דְּדַהֲבָא מַתְקַלְהוֹן:
@43 וַאֲמַר בַּת מָן אַתְּ חַוִּי כְעַן לִי הַאִית בֵּית אָבוּךְ אָתַר כָּשַׁר לָנָא לִמְבָת:
@44 וַאֲמֶרֶת לֵהּ בַּת בְּתוּאֵל אֲנָא בַּר מִלְכָּה דִּילֵידַת לְנָחוֹר:
@45 וַאֲמֶרֶת לֵהּ אַף תִּבְנָא אַף כִּסָּתָא סַגִּי עִמָּנָא אַף אָתַר כָּשַׁר לִמְבָת:
@46 וּכְרַע גַּבְרָא וּסְגִיד קֳדָם יְיָ:
@47 וַאֲמַר בְּרִיךְ יְיָ אֱלָהָא דְרִבּוֹנִי אַבְרָהָם דִּי לָא מְנַע טִיבוּתֵהּ וְקוּשְׁטֵהּ מִן רִבּוֹנִי אֲנָא בְּאוֹרַח תַּקְנָא דַּבְּרַנִּי יְיָ בֵּית אֲחוֹהִי דְרִבּוֹנִי:
@48 וּרְהָטַת עוּלֶמְתָּא וְחַוִּיאַת לְבֵית אִמַּהּ כְּפִתְגָּמַיָּא הָאִלֵּין:
@49 וּלְרִבְקָה אָחָא וּשְׁמֵהּ לָבָן וּרְהַט לָבָן לְוַת גַּבְרָא לְבָרָא לְוַת עֵינָא:
@50 וַהֲוָה כַּד חָזָא יָת קָדָשָׁא וְיָת שֵׁירַיָּא עַל יְדֵי אֲחָתֵהּ וְכַד שְׁמַע יָת פִּתְגָּמֵי רִבְקָה אֲחָתֵהּ לְמֵימַר כְּדֵין מַלֵּיל עִמִּי גַּבְרָא וַאֲתָא לְוַת גַּבְרָא וְהָא קָאֵם עִלַּוֵּי גַּמְלַיָּא עַל עֵינָא:
@51 וַאֲמַר עוּל בְּרִיכָא דַּיְיָ לְמָא אַתְּ קָאֵם בְּבָרָא וַאֲנָא פַּנֵּיתִי בֵיתָא וַאֲתַר כָּשַׁר לְגַמְלַיָּא:
@52 וְעַל גַּבְרָא לְבֵיתָא וּשְׁרָא גַּמְלַיָּא וִיהַב תִּבְנָא וְכִסָּתָא לְגַמְלַיָּא וּמַיָּא לְאַסְחָאָה רַגְלוֹהִי וְרַגְלֵי גֻּבְרַיָּא דְּעִמֵּהּ:
@53 וְשַׁוִּיאוּ קֳדָמוֹהִי לְמֵיכָל וַאֲמַר לָא אֵיכוּל עַד דַּאֲמַלֵּל פִּתְגָּמָי וַאֲמַר מַלֵּיל:
@54 וַאֲמַר עַבְדָּא דְאַבְרָהָם אֲנָא:
@55 וַיְיָ בְּרִיךְ יָת רִבּוֹנִי לַחֲדָא וּרְבָא וִיהַב לֵהּ עָאן וְתוֹרִין וּכְסַף וּדְהַב וְעַבְדִּין וְאַמְהָן וְגַמְלִין וְחַמָרִין:
@56 וִילֵידַת שָׂרָה אִתַּת רִבּוֹנִי בַר לְרִבּוֹנִי בָּתַר דְּסֵיבָת וִיהַב לֵהּ יָת כָּל דִּילֵהּ:
@57 וְקַיֵּם עָלַי רִבּוֹנִי לְמֵימָר לָא תִסַבּ אִתְּתָא לִבְרִי מִבְּנַת כְּנַעֲנָאֵי דִי אֲנָא יָתֵב בְּאַרְעֵהּ:
@58 אֶלָהֵן לְבֵית אַבָּא תֵּזִיל וּלְזַרְעִיתִי וְתִסַּב אִתְּתָא לִבְרִי:
@59 וַאֲמָרִית לְרִבּוֹנִי מָאִים לָא תֵיתֵי אִתְּתָא בַּתְרָי:
@60 וַאֲמַר לִי יְיָ דִּי פְלָחִית קֳדָמוֹהִי יִשְׁלַח מַלְאָכֵהּ עִמָּךְ וְיַצְלַח אָרְחָךְ וְתִסַּב אִתְּתָא לִבְרִי מִזְּרְעִיתִי וּמִבֵּית אַבָּא:
@61 בְּכֵן תְּהֵי זַכַּי (נ''י זַכָּא) מִמּוּמָתִי אֲרֵי תְהַךְ לְזַרְעִיתִי וְאִם לָא יִתְּנוּן לָךְ וּתְהֵי זַכַּי מִמּוּמָתִי:
@62 וְאָתִית (נ''י וַאֲתֵיתִי) יוֹמָא דֵּין לְעֵינָא וַאֲמָרִית יְיָ אֱלָהָא דְּרִבּוֹנִי אַבְרָהָם אִם אִית כְּעַן רַעֲוָא קֳדָמָךְ לְאַצְלָחָא אָרְחִי דִּי אֲנָא אָזֵיל עֲלַהּ:
@63 הָא אֲנָא קָאֵם עַל עֵינָא דְמַיָּא וִיהֵי עוּלֶמְתָּא דְּתִפּוֹק לְמִמְלֵי וְאֵימַר לַהּ אַשְׁקִינִי כְעַן זְעֵיר מַיָּא מִקּוּלְתִיךְ:
@64 וְתֵימַר לִי אַף אַתְּ אֵשְׁתְּ וְאַף לְגַמְלָיךְ אַמְלִי הִיא אִתְּתָא דְּזַמִּין יְיָ לְבַר רִבּוֹנִי:
@65 אֲנָא עַד לָא שֵׁיצִיתִי לְמַלָּלָא בְלִבִּי וְהָא רִבְקָה נְפָקַת וְקוּלְתַהּ עַל כַּתְפַּהּ וּנְחָתַת לְעֵינָא וּמְלָת וַאֲמָרִית לַהּ אַשְׁקִינִי כְעָן:
@66 וְאוֹחִיאַת וַאֲחִיתַת קוּלְתַהּ מִנַּהּ וַאֲמֶרֶת אֵשְׁתְּ וְאַף גַּמְלָךְ אַשְׁקִי וּשְׁתֵיתִי וְאַף גַּמְלַיָּא אַשְׁקִיאַת:
@67 וּשְׁאֵילִית יָתַהּ וַאֲמָרִית בַּת מָן אַתְּ וַאֲמֶרֶת בַּת בְּתוּאֵל בַּר נָחוֹר דִּילֵידַת לֵהּ מִלְכָּה וְשַׁוֵּיתִי קָדָשָׁא עַל אַפַּהּ וְשִׁירַיָּא עַל יְדָהָא:
@68 וּכְרָעִית וּסְגָדִית קֳדָם יְיָ וּבָרֵכִית יָת יְיָ אֱלָהֵהּ דְּרִבּוֹנִי אַבְרָהָם דְּדַבְּרַנִּי בְּאוֹרַח קְשׁוֹט לְמִיסַב יָת בַּת אֲחוּהִי דְּרִבּוֹנִי לִבְרֵהּ:
@69 וּכְעַן אִם אִיתֵיכוֹן עָבְדִין טִיבוּ וּקְשׁוֹט עִם רִבּוֹנִי חַוּוֹ לִי וְאִם לָא חַוּוֹ לִי וְאִתְפְּנֵי עַל יַמִּינָא אוֹ עַל שְׂמָאלָא:
@70 וְאָתֵיב לָבָן וּבְתוּאֵל וַאֲמָרוּ מִן קֳדָם יְיָ נְפַק פִּתְגָּמָא לֵית אֲנַחְנָא יָכְלִין לְמַלָּלָא עִמָּךְ בִּישׁ אוֹ טָב:
@71 הָא רִבְקָה קֳדָמָךְ דְּבַר וְאֵיזִיל וּתְהֵי אִתְּתָא לְבַר רִבּוֹנָךְ כְּמָא דִּי מַלֵּל יְיָ:
@72 וַהֲוָה כַּד שְׁמַע עַבְדָּא דְאַבְרָהָם יָת פִּתְגָּמֵיהוֹן וּסְגֵד עַל אַרְעָא קֳדָם יְיָ:
@73 וְאַפֵּק עַבְדָּא מָנִין דִּכְסַף וּמָנִין דִּדְהַב וּלְבוּשִׁין וִיהַב לְרִבְקָה וּמִגְדָּנִין יְהַב לַאֲחוּהָא וּלְאִמַּהּ:
@74 וַאֲכָלוּ וּשְׁתִיאוּ הוּא וְגוּבְרַיָּא דִּי עִמֵּהּ וּבָתוּ וְקָמוּ בְצַפְרָא וַאֲמַר שַׁלְּחוּנִי לְוַת רִבּוֹנִי:
@75 וַאֲמַר אֲחוּהָ וְאִמַּהּ תָּתֵיב עוּלֶמְתָּא עִמָּנָא עִדַּן בְּעִדַּן אוֹ עַשְׂרָא יַרְחִין בָּתַר כֵּן תֵּיזִיל:
@76 וַאֲמַר לְהוֹן לָא תְאַחֲרוּן יָתִי וַיְיָ אַצְלַח אָרְחִי שַׁלְּחוּנִי וְאֵיהַךְ לְוַת רִבּוֹנִי:
@77 וַאֲמַרוּ נִקְרֵי לְעוּלֶמְתָּא וְנִשְׁמָע מַה דְּהִיא אָמְרָה:
@78 וּקְרוֹ לְרִבְקָה וַאֲמַרוּ לַהּ הֲתֵיזְלִי עִם גַּבְרָא הָדֵין וַאֲמֶרֶת אֵיזִיל:
@79 וְשַׁלָּחוּ יָת רִבְקָה אֲחַתְהוֹן וְיָת מֵנִקְתַּהּ וְיָת עַבְדָּא דְאַבְרָהָם וְיָת גַּבְרוֹהִי:
@80 וּבָרִיכוּ יָת רִבְקָה וַאֲמַרוּ לַהּ אֲחָתָנָא אַתְּ הֲוֵי לְאַלְפִין וּלְרִבְוָן וְיִרְתוּן בְּנַיְכִי יָת קִרְוֵי סַנְאֵיהוֹן:
@81 וְקָמַת רִבְקָה וְעוּלֶמְתָּהָא וּרְכִיבָא עַל גַּמְלַיָּא וְאָזְלָּא בָּתַר גַּבְרָא וּדְבַר עַבְדָּא יָת רִבְקָה וַאֲזָל:
@82 וְיִצְחָק אָתָא מִמֵּתוֹהִי (נ''י עַל בְּמֵיתוֹהִי) מִבֵּירָא דְמַלְאָךְ קַיָּמָא אִתְחֲזֵי עֲלַהּ וְהוּא יָתֵב בַּאֲרַע דָּרוֹמָא:
@83 וּנְפַק יִצְחָק לְצַלָּאָה בְחַקְלָא לְמִפְנֵי רַמְשָׁא וּזְקַף עֵינוֹהִי וַחֲזָא וְהָא גַּמְלַיָּא אָתָן:
@84 וּזְקָפַת רִבְקָה יָת עֵינָהָא וַחֲזַת יָת יִצְחָק וְאִתְרְכִינַת מֵעַל גַּמְלָא:
@85 וַאֲמֶרֶת לְעַבְדָּא מָן גַּבְרָא דֵיכִי דִּמְהַלֵּךְ בְּחַקְלָא לְקַדָּמוּתָנָא וַאֲמַר עַבְדָּא הוּא רִבּוֹנִי וּנְסֵיבַת עֵיפָא וְאִתְכַּסִּיאַת:
@86 וְאִשְׁתָּעֵי עַבְדָּא לְיִצְחָק יָת כָּל פִּתְגָּמַיָּא דִּי עֲבָד:
@87 וְאַעֲלַהּ יִצְחָק לְמַשְׁכְּנָא וַחֲזָא וְהָא תַקְּנִין עוֹבָדָהָא כְּעוֹבָדֵי שָׂרָה אִמֵּהּ וּנְסֵיב יָת רִבְקָה וַהֲוַת לֵהּ לְאִנְּתּוּ וּרְחִימַהּ וְאִתְנְחֵם יִצְחָק בָּתַר דְּמִיתַת אִמֵּהּ:
@88 וְאוֹסֵיף אַבְרָהָם וּנְסֵיב אִתְּתָא וּשְׁמַהּ קְטּוּרָה:
@89 וִילֵידַת לֵהּ יָת זִמְרָן וְיָת יָקְשָׁן וְיָת מְדָן וְיָת מִדְיָן וְיָת יִשְׁבָּק וְיָת שׁוּחַ:
@90 וְיָקְשָׁן אוֹלִיד יָת שְׁבָא וְיָת דְּדָן וּבְנֵי דְדָן הֲווֹ לְמַשִּׁירְיָן וְלִשְׁכוּנִין וּלְּנַגְוָן:
@91 וּבְנֵי מִדְיָן עֵיפָה וָעֵפֶר וַחֲנוֹךְ וַאֲבִידָע וְאֶלְדָּעָה כָּל אִלֵּין בְּנֵי קְטוּרָה:
@92 וִיהַב אַבְרָהָם יָת כָּל דִּילֵהּ לְיִצְחָק:
@93 וְלִבְנֵי לְחֵינָתָא דִּי לְאַבְרָהָם יְהַב אַבְרָהָם מַתְּנָן וְשַׁלְחִנּוּן מֵעַל יִצְחָק בְּרֵהּ בְּעוֹד דְּהוּא קַיָּם קִידוּמָא לַאֲרַע מַדִינְחָא:
@94 וְאִלֵּין יוֹמֵי שְׁנֵי חַיֵּי אַבְרָהָם דַּחֲיָא מְאָה וְשַׁבְעִין וְחָמֵשׁ שְׁנִין:
@95 וְאִתְנְגִיד וּמִית אַבְרָהָם בְּסִיבוּ טָבָא סִיב וּשְׂבַע יוֹמִין וְאִתְכְּנִישׁ לְעַמֵּהּ:
@96 וּקְבָרוּ יָתֵהּ יִצְחָק וְיִשְׁמָעֵאל בְּנוֹהִי בִּמְעָרַת כָּפֶלְתָּא בַּחֲקַל עֶפְרוֹן בַּר צֹחַר חִתָּאָה דִּי עַל אַפֵּי מַמְרֵא:
@97 חַקְלָא דִּי זְבַן אַבְרָהָם מִן בְּנֵי חִתָּאָה תַּמָּן אִתְקְבַר אַבְרָהָם וְשָׂרָה אִתְּתֵהּ:
@98 וַהֲוָה בָּתַר דְּמִית אַבְרָהָם וּבָרֵךְ יְיָ יָת יִצְחָק בְּרֵהּ וִיתֵב יִצְחָק עִם בֵּירָא דְמַלְאָךְ קַיָּמָא אִתְחֲזֵי עֲלַהּ:
@99 וְאִלֵּין תּוּלְדַת יִשְׁמָעֵאל בַּר אַבְרָהָם דִּי יְלֵידַת הָגָר מִצְרֵתָא אַמְתָא דְשָׂרָה לְאַבְרָהָם:
@100 וְאִלֵּין שְׁמָהַת בְּנֵי יִשְׁמָעֵאל בִּשְׁמָהַתְהוֹן לְתוּלְדַתְהוֹן בּוּכְרָא דְיִשְׁמָעֵאל נְבָיוֹת וְקֵדָר וְאַדְבְּאֵל וּמִבְשָׂם:
@101 וּמִשְׁמָע וְדוּמָה וּמַשָּׂא:
@102 חֲדַד וְתֵימָא יְטוּר נָפִישׁ וָקֵדְמָה:
@103 אִלֵּין אִנּוּן בְּנֵי יִשְׁמָעֵאל וְאִלֵּין שְׁמָהַתְהוֹן בְּפַצְחֵיהוֹן וּבִכְרַכֵּיהוֹן תְּרֵין עֲסַר רַבְרְבִין לְאֻמֵּיהוֹן:
@104 וְאִלֵּין שְׁנֵי חַיֵּי יִשְׁמָעֵאל מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין וְאִתְנְגִיד וּמִית וְאִתְכְּנִישׁ לְעַמֵּהּ:
@105 וּשְׁרוֹ מֵחֲוִילָה עַד חַגְרָא דִּי עַל אַפֵּי מִצְרַיִם מָטֵי לְאָתוּר עַל אַפֵּי כָל אֲחוֹהִי שְׁרָא: פפפ:

@1 **ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים.** לכך נכתב שנה בכל כלל וכלל, לומר לך שכל אחד נדרש לעצמו, בת מאה כבת עשרים לחטא, מה בת עשרים לא חטאה, שהרי אינה בת ענשין, אף בת מאה בלא חטא, ובת עשרים כבת שבע ליופי: **שני חיי שרה.** כלן שוין לטובה:
@2 **בקרית ארבע.** על שם ארבע ענקים שהיו שם אחימן ששי ותלמי ואביהם. דבר אחר על שם ארבעה זוגות שנקברו שם איש ואשתו אדם וחוה, אברהם ושרה, יצחק ורבקה, יעקב ולאה: **ויבא אברהם.** מבאר שבע: **לספוד לשרה ולבכתה.** ונסמכה מיתת שרה לעקידת יצחק, לפי שעל ידי בשורת העקידה שנזדמן בנה לשחיטה וכמעט שלא נשחט, פרחה נשמתה ממנה ומתה:
@4 **גר ותושב אנכי עמכם.** גר מארץ אחרת ונתישבתי עמכם. ומדרש אגדה אם תרצו הריני גר, ואם לאו אהיה תושב ואטלנה מן הדין שאמר לי הקדוש ברוך הוא (לעיל יב ז) לזרעך אתן את הארץ הזאת: **אחזת קבר.** אחוזת קרקע לבית הקברות:
@6 **לא יכלה.** לא ימנע, כמו (תהלים מ יב) לא תכלא רחמיך, וכמו (לעיל ח ב) ויכלא הגשם:
@8 **נפשכם.** רצונכם: **ופגעו לי.** לשון בקשה, כמו (רות א טז) אל תפגעי בי:
@9 **המכפלה.** בית ועליה על גביו. דבר אחר שכפולה בזוגות: **בכסף מלא.** אשלם כל שויה, וכן דוד אמר לארונה (דברי הימים א' כא כד) בכסף מלא:
@10 **ועפרון ישב.** כתיב חסר, אותו היום מנוהו שוטר עליהם, מפני חשיבותו של אברהם שהיה צריך לו עלה לגדלה: **לכל באי שער עירו.** שכלן בטלו ממלאכתן ובאו לגמול חסד לשרה:
@11 **לא אדני.** לא תקנה אותה בדמים: **נתתי לך.** הרי הוא כמו שנתתיה לך:
@13 **אך אם אתה לו שמעני.** אתה אומר לי לשמוע לך ולקח בחנם, אני אי אפשי בכך, אך אם אתה לו שמעני הלואי ותשמעני: **נתתי.** דונא''י בלע''ז [נתתי] מוכן הוא אצלי והלואי נתתי לך כבר:
@15 **ביני ובינך.** בין שני אוהבים כמונו מה היא חשובה לכלום, אלא הנח את המכר ואת מתך קבור:
@16 **וישקל אברהם לעפרן.** חסר וי''ו, לפי שאמר הרבה ואפלו מעט לא עשה, שנטל ממנו שקלים גדולים שהן קנטרין, שנאמר (פסוק טז) עבר לסוחר, שמתקבלים בשקל בכל מקום ויש מקום ששקליהן גדולים שהן קנטרין, צינטינייר''ש [מטבעות של מאה] בלע''ז :
@17 **ויקם שדה עפרון.** תקומה היתה לה שיצאה מיד הדיוט ליד מלך. ופשוטו של מקרא ויקם השדה והמערה אשר בו וכל העץ לאברהם למקנה וגו':
@18 **בכל באי שער עירו.** בקרב כלם ובמעמד כלם הקנהו לו:
@21 **ברך את אברהם בכל.** בכל עולה בגימטריא בן, ומאחר שהיה לו בן היה צריך להשיאו אשה:
@22 **זקן ביתו.** לפי שהוא דבוק נקוד זקן: **תחת ירכי.** לפי שהנשבע צריך שיטול בידו חפץ של מצוה, כגון ספר תורה או תפלין, והמילה היתה מצוה ראשונה לו ובאה לו על ידי צער והיתה חביבה עליו ונטלה:
@27 **ה' אלהי השמים אשר לקחני מבית אבי.** ולא אמר ואלהי הארץ, ולמעלה אמר (פסוק ג) ואשביעך בה' אלהי השמים ואלהי הארץ. אמר לו עכשיו הוא אלהי השמים ואלהי הארץ, שהרגלתיו בפי הבריות, אבל כשלקחני מבית אבי היה אלהי השמים ולא אלהי הארץ, שלא היו באי עולם מכירים בו, ושמו לא היה רגיל בארץ: **מבית אבי.** מחרן: **ומארץ מולדתי.** מאור כשדים: **ואשר דבר לי.** לצרכי, כמו (מל''א ב ד) אשר דבר עלי, וכן כל לי ולו ולהם הסמוכים אצל דבור מפורשים בלשון על, ותרגום שלהם עלי עלוהי עליהון, שאין נופל אצל דבור לשון לי ולו ולהם, אלא אלי אליו אליהם ותרגום שלהם עמי עמיה עמהון, אבל אצל אמירה נופל לשון לי ולו ולהם: **ואשר נשבע לי.** בין הבתרים:
@28 **ונקית משבועתי** וגו' **.** וקח לו אשה מבנות ענר אשכול וממרא: **רק את בני** וגו' **.** רק, מעוט הוא. בני אינו חוזר, אבל יעקב בן בני, סופו לחזור:
@30 **מגמלי אדניו.** נכרין היו משאר גמלים, שהיו יוצאין זמומין מפני הגזל שלא ירעו בשדות אחרים: **וכל טוב אדניו בידו.** שטר מתנה כתב ליצחק על כל אשר לו, כדי שיקפצו לשלוח לו בתם: **ארם נהרים.** בין שתי נהרות יושבת:
@31 **ויברך הגמלים.** הרביצם:
@34 **אתה הכחת.** ראויה היא לו שתהא גומלת חסדים וכדאי לכנס בביתו של אברהם. ולשון הוכחת בררת, אפרוביש''ט בלע''ז : **ובה אדע.** לשון תחנה, הודע לי בה: **כי עשית חסד.** אם תהיה ממשפחתו והוגנת לו, אדע כי עשית חסד:
@36 **בתולה.** ממקום בתולים: **ואיש לא ידעה.** שלא כדרכה, לפי שבנות הגוים היו משמרות מקום בתוליהן ומפקירות עצמן ממקום אחר, העיד על זו שנקיה מכל:
@37 **וירץ העבד לקראתה.** לפי שראה שעלו המים לקראתה: **הגמיאיני נא.** לשון גמיעה, הומיי''ר בלע''ז :
@38 **ותרד כדה.** מעל שכמה:
@39 **עד אם כלו.** הרי אם משמש בלשון אשר, אם כלו, דיספקון, שזו היא גמר שתיתן כששתו די ספוקן:
@40 **ותער.** לשון נפיצה, והרבה יש בלשון משנה (עבודה זרה ה ז) המערה מכלי אל כלי, ובמקרא יש לו דומה (תהלים קמא ח) אל תער נפשי, (ישעיה נג יב) אשר הערה למות נפשו: **השקת.** אבן חלולה ששותים בה הגמלים:
@41 **משתאה.** לשון שאיה, כמו (ישעיה ו יא) שאו ערים, תשאה שממה: **משתאה.** משתומם ומתבהל על שראה דברו קרוב להצליח. אבל אינו יודע אם ממשפחת אברהם היא אם לאו. ואל תתמה בתי''ו של משתאה שאין לך תיבה שתחלת יסודה שי''ן ומדברת בלשון מתפעל שאין תי''ו מפרידה בין שתי אותיות של עיקר היסוד כגון משתאה מגזרת שאה, (ישעיה נט טו) משתולל מגזרת שולל, (שם נט טו) וישתומם מגזרת שממה, (מיכה ו טז) וישתמר חקות עמרי מגזרת וישמר, אף כאן משתאה מגזרת תשאה, וכשם שאתה מוצא לשון משומם באדם נבהל ונאלם ובעל מחשבות, כמו (איוב יח כ) על יומו נשמו אחרונים, (ירמיה ב יב) שמו שמים, (דניאל ד טז) אשתומם כשעה חדא, כך תפרש לשון שאיה באדם בהול ובעל מחשבות. ואונקלוס תרגם לשון שהיה וגוברא שהי, שוהא ועומד במקום אחד לראות ההצליח ה' דרכו. ואין לתרגם שתי, שהרי אינו לשון שתיה, שאין אל''ף נופלת בלשון שתיה: **משתאה לה.** משתומם עליה כמו (לעיל כ יג) אמרי לי אחי הוא, וכמו (לקמן כו ז) וישאלו אנשי המקום לאשתו:
@42 **בקע.** רמז לשקלי ישראל בקע לגלגלת: **ושני צמידים.** רמז לשני לוחות מצמדות: **עשרה זהב משקלם.** רמז לעשרת הדברות שבהן:
@43 **ויאמר בת מי את.** לאחר שנתן לה שאלה, לפי שהיה בטוח בזכותו של אברהם שהצליח הקדוש ברוך הוא דרכו: **ללין.** לינה אחת. לין שם דבר והיא אמרה ללון כמה לינות:
@44 **בת בתואל.** השיבתו על ראשון ראשון ועל אחרון אחרון:
@45 **מספוא.** כל מאכל הגמלים קרוי מספוא כגון תבן ושעורים:
@47 **בדרך.** דרך המימן, דרך הישר, באותו דרך שהייתי צריך. וכן כל בי''ת ולמ''ד וה''א המשמשים בראש התבה ונקודים בפת''ח מדברים בדבר הפשוט שנזכר כבר במקום אחר או שהוא מבורר וניכר באיזו הוא מדבר:
@48 **לבית אמה.** דרך הנשים היתה להיות להן בית לישב בו למלאכתן, ואין הבת מגדת אלא לאמה:
@49 **וירץ.** למה וירץ ועל מה רץ, ויהי כראות את הנזם, אמר עשיר הוא זה, ונתן עיניו בממון:
@50 **על הגמלים.** לשמרן, כמו (לעיל יח ח) והוא עומד עליהם, לשמשם:
@51 **פניתי הבית.** מעבודה זרה:
@52 **ויפתח.** התיר זמם שלהם, שהיה סותם את פיהם שלא ירעו בדרך בשדות אחרים:
@53 **עד אם דברתי.** הרי אם משמש בלשון אשר ובלשון כי, כמו (לקמן מט י) עד כי יבא שילה, וזה שאמרו חכמינו זכרונם לברכה כי משמש בארבע לשונות, והאחת אי, והוא אם:
@56 **ויתן לו את כל אשר לו.** שטר מתנה הראה להם:
@57 **לא תקח אשה לבני מבנות הכנעני.** אם לא תלך תחלה אל בית אבי ולא תאבה ללכת אחריך:
@59 **אלי לא תלך האשה.** אלי כתיב, בת היתה לו לאליעזר והיה מחזר למצוא עלה שיאמר לו אברהם לפנות אליו להשיאו בתו, אמר לו אברהם בני ברוך ואתה ארור, ואין ארור מדבק בברוך:
@62 **ואבא היום.** היום יצאתי והיום באתי, מכאן שקפצה לו הארץ. אמר רבי אחא יפה שיחתן של עבדי אבות לפני המקום מתורתן של בנים, שהרי פרשה של אליעזר כפולה בתורה, והרבה גופי תורה לא נתנו אלא ברמיזה:
@64 **גם אתה.** גם לרבות אנשים שעמו: **הכיח.** ברר והודיע, וכן כל הוכחה שבמקרא ברור דבר:
@65 **טרם אכלה.** טרם שאני מכלה, וכן כל לשון הוה פעמים שהוא מדבר בלשון עבר ויכול לכתוב כמו טרם כליתי, ופעמים שמדבר בלשון עתיד, כמו (איוב א ה) כי אמר איוב, הרי לשון עבר, (שם) ככה יעשה איוב הרי לשון עתיד. ופירוש שניהם לשון הווה, כי אומר היה איוב (שם) אולי חטאו בני וגו' והיה עושה כך:
@67 **ואשאל ואשים.** שנה הסדר, שהרי הוא תחלה נתן ואחר כך שאל, אלא שלא יתפשוהו בדבריו ויאמרו היאך נתת לה, ועדיין אינך יודע מי היא:
@69 **על ימין.** מבנות ישמעאל: **על שמאל.** מבנות לוט שהיה יושב לשמאלו של אברהם:
@70 **ויען לבן ובתואל.** רשע היה וקפץ להשיב לפני אביו: **לא נוכל דבר אליך.** למאן בדבר הזה, לא על ידי תשובת דבר רע ולא על ידי תשובת דבר הגון לפי שנכר שמה' יצא הדבר, לפי דבריך שזמנה לך:
@72 **וישתחו ארצה.** מכאן שמודים על בשורה טובה:
@73 **ומגדנות.** לשון מגדים, שהביא עמו מיני פירות של ארץ ישראל:
@74 **וילינו.** כל לינה שבמקרא לינת לילה אחד:
@75 **ויאמר אחיה ואמה.** ובתואל היכן היה, הוא היה רוצה לעכב ובא מלאך והמיתו: **ימים.** שנה, כמו (ויקרא כה כט) ימים תהיה גאלתו, שכך נותנין לבתולה זמן שנים עשר חדש לפרנס את עצמה בתכשיטים: **או עשור.** עשרה חדשים. ואם תאמר ימים ממש, אין דרך המבקשים לבקש דבר מועט ואם לא תרצה תן לנו מרבה מזה:
@77 **ונשאלה את פיה.** מכאן שאין משיאין את האשה אלא מדעתה:
@78 **ותאמר אלך.** מעצמי, ואף אם אינכם רוצים:
@80 **את היי לאלפי רבבה.** את וזרעך תקבלו אותה ברכה שנאמר לאברהם בהר המוריה (לעיל כב יז) הרבה ארבה את זרעך וגו' . יהי רצון שיהא אותו הזרע ממך ולא מאשה אחרת:
@82 **מבוא באר לחי ראי.** שהלך להביא הגר לאברהם אביו שישאנה: **יושב בארץ הנגב.** קרוב לאותו באר, שנאמר (לעיל כ א) ויסע משם אברהם ארצה הנגב וישב בין קדש ובין שור, ושם היה הבאר, שנאמר (שם טז יד) הנה בין קדש ובין ברד:
@83 **לשוח.** לשון תפלה, כמו (תהלים קב א) ישפוך שיחו:
@84 **ותרא את יצחק.** ראתה אותו הדור ותוהא מפניו: **ותפל.** השמיטה עצמה לארץ, כתרגומו ואתרכינת הטתה עצמה לארץ ולא הגיעה עד הקרקע, כמו (פסוק יד) הטי נא כדך, ארכיני, (ש''ב כב י) ויט שמים, וארכין, לשון מטה לארץ, ודומה לו (תהלים לז כד) כי יפל לא יוטל, כלומר אם יטה לארץ לא יגיע עד הקרקע:
@85 **ותתכס.** לשון ותתפעל, כמו ותקבר, ותשבר:
@86 **ויספר העבד.** גלה לו נסים שנעשו לו שקפצה לו הארץ ושנזדמנה לו רבקה בתפלתו:
@87 **האהלה שרה אמו.** ויביאה האהלה ונעשית דגמת שרה אמו, כלומר והרי היא שרה אמו, שכל זמן ששרה קימת היה נר דלוק מערב שבת לערב שבת, וברכה מצויה בעיסה, וענן קשור על האהל, ומשמתה פסקו, וכשבאת רבקה חזרו: **אחרי אמו.** דרך ארץ כל זמן שאמו של אדם קימת כרוך הוא אצלה, ומשמתה הוא מתנחם באשתו:
@88 **קטורה.** זו הגר, ונקראת קטורה על שם שנאים מעשיה כקטרת ושקשרה פתחה שלא נזדוגה לאדם מיום שפרשה מאברהם:
@90 **אשורם ולטושם.** שם ראשי אומות. ותרגום של אנקלוס אין לי לישבו על לשון המקרא. שפרש למשרין, לשון מחנה. ואם תאמר שאינו כן מפני האל''ף שאינה יסודית, הרי לנו תבות שאין בראשם אל''ף ונתוספה אל''ף בראשם, כמו (עמוס ז ז) חומת אנך, שהוא מן (שמואל ב' ד ד) נכה רגלים, וכמו (מלכים ב' ד ב) אסוך שמן שהוא מן (רות ג ג) ורחצת וסכת: **ולטושם.** הם בעלי אהלים המתפזרים אנה ואנה ונוסעים איש באהלי אפדנו, וכן הוא אומר (ש''א ל טז) והנה נטושים על פני כל הארץ, שכן למ''ד ונו''ן מתחלפות זו בזו:
@92 **ויתן אברהם** וגו' **.** אמר ר' נחמיה ברכה דיאתיקי, שאמר לו הקדוש ברוך הוא לאברהם (לעיל יב ב) והיה ברכה, הברכות מסורות בידך לברך את מי שתרצה, ואברהם מסרם ליצחק:
@93 **הפילגשים.** חסר כתיב, שלא היתה אלא פלגש אחת, היא הגר היא קטורה. נשים בכתבה, פילגשים בלא כתבה, כדאמרינן בסנהדרין (כא א) בנשים ופילגשים דדוד: **נתן אברהם מתנת.** פרשו רבותינו שם טמאה מסר להם. דבר אחר מה שנתן לו על אודות שרה ושאר מתנות שנתנו לו, הכל נתן להם שלא רצה להנות מהם:
@94 **מאת שנה ושבעים שנה וחמש שנים.** בן מאה כבן שבעים, ובן שבעים כבן חמש בלא חטא:
@96 **יצחק וישמעאל.** מכאן שעשה ישמעאל תשובה והוליך את יצחק לפניו, והיא שיבה טובה שנאמר באברהם:
@98 **ויהי אחרי מות אברהם ויברך** וגו' **.** נחמו תנחומי אבלים. דבר אחר אף על פי שמסר הקדוש ברוך הוא את הברכות לאברהם, נתיירא לברך את יצחק מפני שצפה את עשו יוצא ממנו, אמר יבא בעל הברכות ויברך את אשר ייטב בעיניו ובא הקדוש ברוך הוא וברכו:
@100 **בשמתם לתולדתם.** סדר לידתן זה אחר זה:
@103 **בחצריהם.** כרכים שאין להם חומה, ותרגומו בפצחיהון, שהם מפוצחים לשון פתיחה, כמו (תהלים צח ד) פצחו ורננו:
@104 **ואלה שני חיי ישמעאל** וגו' **.** אמר רבי חייא בר אבא למה נמנו שנותיו של ישמעאל, כדי ליחס בהם שנותיו של יעקב. מן שנותיו של ישמעאל למדנו ששמש יעקב בבית עבר ארבע עשרה שנה כשפרש מאביו קודם שבא אצל לבן, שהרי כשפרש יעקב מאביו מת ישמעאל, שנאמר (להלן כח ט) וילך עשו אל ישמעאל וגו' , כמו שמפורש בסוף מגלה נקראת (מגילה יז א) : **ויגוע.** לא נאמרה גויעה אלא בצדיקים:
@105 **נפל.** שכן, כמו (שופטים ז יב) מדין ועמלק וכל בני קדם נופלים בעמק. כאן הוא אומר לשון נפילה, ולהלן הוא אומר על פני כל אחיו ישכן (לעיל טז יב) , עד שלא מת אברהם ישכן, משמת אברהם נפל:

@1 **מאה שנה ועשרים שנה** . לשון רש"י לכך נכתב שנה בכל כלל וכלל לומר לך שכל אחד נדרש לעצמו בת מאה כבת עשרים לחטא ובת עשרים כבת שבע ליופי וכן כתב בשני חיי אברהם (להלן כה ז) ואין מדרשו זה נכון שהרי בשני חיי ישמעאל (שם פסוק יז) נאמר כשני חיי אברהם בשוה ולא היו שוים בטובה אבל היה מתחלה רשע ועשה תשובה בסוף ועוד כי שנה שנה לחלק משמע ואיננו נדרש להשוותן אבל "שנה שנה ושנים" דרך הלשון הוא ומה שאמרו בבראשית רבה (נח א) בת מאה כבת עשרים לחטא לא דרשו כן אלא מיתור הלשון שחזר ואמר "שני חיי שרה" שכללן והשוה אותן ולא ידרשו כן באברהם
@2 **ויבא אברהם** . לשון רש"י מבאר שבע ואין זה לומר שהיה עומד שם ממה שכתוב (לעיל כב יט) וישב אברהם בבאר שבע כי איך תהיה שרה בחברון אבל הכוונה לומר שהלך שם ביום לצרכו ושמע במיתת שרה ובא משם לספוד לה ולבכותה ולשון רבותינו (ב"ר נח ה) מהר המוריה בא וכן הוא לפי המדרש שכתבו הרב (רש"י כאן) כי שמעה בעקידה ופרחה נשמתה והנראה בעקידה שהיתה הצואה בה בבאר שבע כי שם היה דר ושם חזר כי כן כתוב בתחילה (לעיל כא לג) ויטע אשל בבאר שבע ויקרא שם בשם ה' אל עולם ואמר (שם) ויגר אברהם בארץ פלשתים ימים רבים והוא גרותו בבאר שבע שהוא בארץ פלשתים ושם נצטווה בעקידה ועל כן שהה בדרך שלשה ימים שארץ פלשתים רחוקה מירושלים שאילו חברון בהר יהודה הוא כי כן כתוב (יהושע כ ז) וקרוב לירושלים ובשובו מן העקידה לבאר שבע חזר כמו שנאמר (לעיל כב יט) וישב אברהם אל נעריו ויקומו וילכו יחדו אל באר שבע וישב אברהם בבאר שבע להורות שנתעכב שם וישב בו שנים ואם כן לא מתה שרה באותו זמן כי לא היה אברהם דר בבאר שבע ושרה דרה בחברון וכן נראה כי יצחק נולד בבאר שבע כי כתוב תחילה (לעיל כ א) ויסע משם אברהם ארצה הנגב וישב בין קדש ובין שור ויגר בגרר ואבימלך אמר אליו הנה ארצי לפניך כטוב בעיניך שב (שם טו) ונתישב שם בארץ ההיא בבאר שבע שכן כתוב (לעיל כא כב) ויהי בעת ההיא ויאמר אבימלך ופיכול שר צבאו אל אברהם לאמר ואין כתוב שהלכו אליו מגרר ויכרתו שם הברית בבאר שבע וכן תראה כי הגר כאשר הוציאו אותה מבית אברהם ביום הגמל את יצחק הלכה במדבר באר שבע (לעיל כא יד) ששם היו דרים אבל אחר ימים רבים נסע מארץ פלשתים ובא לחברון ונפטרה שם הצדקת אבל לפי המדרש צריכין אנו לומר כי אברהם ושרה בזמן העקידה היו דרים בחברון ושם נצטוה ומה שאמר ביום השלישי וישא אברהם את עיניו (לעיל כב ד) כי לא נגלה לו ההר חמד אלהים עד היום השלישי והיה בשני הימים הולך בסביבי ירושלים ולא היה הרצון להראות לו ואברהם אחר העקידה לא שב למקומו לחברון אבל הלך תחלה אל באר שבע מקום האשל שלו לתת הודאה על נסו ושם שמע במיתת שרה ובא ומי שאמר מהר המוריה בא ומי שאמר מבאר שבע בא הכל טעם אחד ולפי זה מה שאמר הכתוב וישב אברהם בבאר שבע (לעיל כב יט) יהיה ענינו כי בשובו מן העקידה שב אל באר שבע ומשם הלך לקבור את שרה ואחר הקבורה מיד חזר לבאר שבע ונתישב שם שנים והשלים הכתוב ענין באר שבע כאחד ואחרי כן ספר בקבורה ושם בבאר שבע נשא יצחק את רבקה כמו שאמר והוא יושב בארץ הנגב (להלן כד סב) וזה דעת כל המפרשים (רש"י והראב"ע והרד"ק) כי אברהם היה במקום אחר ובא משם ולפי דעתי כי היה לשרה אהל שם עומדת ואמהותיה לפניה וכן כתוב (להלן לא לג) באהל יעקב ובאהל לאה ובאהל שתי האמהות והנה שרה מתה באהל אשר לה ונכנס אברהם באהל עם אחזת מרעיו לספוד אותה או שיהיה לשון "ויבא" לאמר שנתעורר אברהם להספד הזה והתחיל לעשותו כי כל מתעורר ומתחיל במלאכה יקרא בא אליה וזה לשון מורגל בדברי חכמים כמו ששנינו בתמיד (פ"ד מ"ג) בא לו לגרה והניח בה שתי צלעות מכאן בא לו לדופן השמאלית בא לו לעוקץ ואמרם (בכורות כ) אני לא באתי לידי המדה הזו וכן בכתוב (שמות כב יד) בא בשכרו שבא למלאכה ההיא ועשה אותה בעבור שכרו ולא יתכן בעיני שבא מעיר אחרת אל חברון שאלו היה כן היה מזכיר אותו המקום והיה הכתוב מפרש "וישמע אברהם ויבא ממקום פלוני"
@4 **גר ותושב אנכי עמכם** . היה המנהג להיות להם בתי קברות איש לבית אבותיו ושדה קבורה אחד יקברו בו כל הגרים והנה אברהם אמר אל בני חת אני גר מארץ אחרת ולא הנחלתי מאבותי בית הקברות בארץ הזאת והנה עתה אני תושב עמכם כי חפצתי לשבת בארץ הזאת ולכן תנו קבר להיות לי לאחזת עולם כאחד מכם ומפני שאמר "תנו" חשבו שבקש אותה מהם במתנה וענו אותו אינך נחשב בעינינו כגר ותושב אבל אתה מלך המליכך האלהים עלינו ואנחנו ואדמתנו עבדים לך תקח כל בית הקברות שתחפוץ בו וקבור מתך שם ויהיה לך לאחזת קבר לעולם כי איש ממנו לא ימנעהו ממך
@8 **אם יש את נפשכם לקבור את מתי מלפני** . טעמו אני לא אקבור מתי בקבר אחר אבל אם רצונכם שאקבור מתי פגעו לי בעפרון שיש לו מערה בקצה שדהו ואיננה לו בית קברות אבותיו כי לשדה היא להם וטעם מלפני כי אם לא תעשו כן אקברנו בארון או יהיה טעמו מתי אשר הוא לפני ואני צריך למהר לקברו וטעם ופגעו לי כי היה עפרון עשיר ונכבד כאשר אמר ביני וביניך מה היא ולא יהיה לו לכבוד למכור נחלת אבותיו כענין נבות היזרעאלי (עיין מלכים א כא) על כן לא הלך אברהם אליו להרבות לו מחיר השדה ובקש מאנשי העיר שיפגעו בעבורו דרך כבוד
@9 **וטעם ויתן לי ויתננה לי** . שאחשוב אותה כמתנה אם בכסף מלא אקחנה ממנו ועל כן לא הזכיר לשון מכירה וכן אוכל בכסף תשברני ומים בכסף תתן לי (דברים ב כח) שהמים הנתנים במתנה אתן בהם כסף או שהוא דרך הלשון להזכיר כן במכירות
@9 "מערת המכפלה" - לשון רש"י בית ועליה על גביו דבר אחר שכפולה בזוגות (עירובין נג) ואיננו נכון כי הכתוב אמר שדה עפרון אשר במכפלה (להלן פסוק יז) והנה הוא שם המקום אשר בו השדה ואין צורך לבקש טעם לשם המקומות ובבראשית רבה (נח ח) אמרו שכפל הקב"ה קומתו של אדם הראשון וקברו בתוכה ועל דעתם היה כל המקום ההוא נקרא כן מעולם והם לא ידעו טעמו כי עפרון בדמי השדה מכר לו הכל על דעתו שאין שם קבר והנה אברהם לא היה מבקש רק למכור לו המערה כי היא בקצה השדה וישאר השדה לעפרון והוא אמר לו דרך מוסר או מרמה שיתן לו השדה והמערה אשר בו כי לא יתכן לאדם נכבד כמוהו שתהיה לו המערה לאחזת קבר והשדה יהיה לאחר ואברהם שמח בכך וקנה הכל בדמים שהזכיר לו
@11 **וטעם לעיני בני עמי** . לאמר הנה כל העם הנה והם היודעים ועדים ואל תחוש לכפירה או לחזרה וקבור מתך שם מעתה כי שלך היא ולא אוכל לשוב ואברהם לא עשה כן כי גם אחרי שפרע הכסף מלא החזיק תחלה בשדה ובמערה והקימם ברשותו לעיני בני העיר וכל באי שער העיר הסוחרים והגרים הנמצאים שם ואחר כן קבר אותה
@13 **אם אתה לו שמעני** . שעורו אם אתה אם תשמעני וענינו כמו אם אתה תשמעני ובא הכפל לנחץ הענין כמו סורה אדני סורה אלי (שופטים ד יח) הטוב טוב אתה (שם יא כה) וכן ולאמר עליו לאמר (דהי"ב לב יז) וכן ואני אנה אני בא (להלן לז ל) ופניתי אני וראיתי אני (קהלת ב יב יג)) כי כל העדה כלם קדושים (במדבר טז ג) כלם רידוף הענין וכן על דעתי אם מחוט ועד שרוך נעל ואם אקח (לעיל יד כג) שעורו אם מחוט ועד שרוך נעל אקח מכל אשר לך או יאמר אם אתה כאשר אמרת כלומר שפיך ולבך שוים בענין ואם תשמעני וכן ויאמרו להם אחיהם מה אתם (שופטים יח ח) ודומה ללשון הזה על דעתי למה זה אנכי (להלן כה כב) אולי זה דעת אונקלוס שאמר אם את עבד לי טיבו שתעשה רצוני כאשר אמרת
@15 **וטעם ארץ ארבע מאות שקל כסף** . על דעת אונקלוס שהיא שוה כן אולי רצה לומר שהיו דמיה קצובים כן במקום ההוא כי כן המנהג ברוב הארצות להיות מחיר שדה קצוב לפי מדתו וכדברי רבותינו (ב"מ פז) עפרון קצב דמים כרצונו ביוקר גדול ואברהם בנדבת לבו שמע ועשה כרצונו והגדיל ועל דרך הפשט "ארץ ארבע מאות שקל כסף" שקנה אותה בכך עפרון או אבותיו הקדמונים
@19 **וטעם ואחרי כן קבר אברהם את שרה אשתו אל מערת שדה המכפלה וגו' היא חברון בארץ כנען** . כי שב לבאר השדה והמקום והארץ בעבור כי כל הפרשה הזכירה בני חת ועפרון החתי לפיכך הזכיר בסוף כי הוא בארץ כנען אשר היא ארץ ישראל וכן אמר בתחילת הפרשה בקרית ארבע היא חברון בארץ כנען וכל זה לבאר כי הצדקת מתה בארץ ישראל ושם נקברה כי החתים ממשפחות כנען ולפי דעתי כי טעם הכתובים אינו אלא להזכיר כי היא ארץ כנען לא ארץ פלשתים כי מפני שאמר ויגר אברהם בארץ פלשתים ימים רבים (לעיל כא לד) וכל מגוריו בארץ ההיא בגרר ונחל גרר ובאר שבע ומשם לחברון ומחברון לשם על כן הזכיר כי חברון הוא בארץ הכנעני היושב בהר ההוא לא בארץ פלשתים הנזכרת לאברהם והוסיף בסוף להודיע המערה שהיא בשדה המכפלה על פני ממרא שזה השם הנודע אליה ונכתבה זאת הפרשה להודיע חסדי השם עם אברהם שהיה נשיא אלהים בארץ אשר בא לגור שם והיחיד וכל העם היו קוראין לו "אדוני" והוא לא אמר להם כן שהיה שר וגדול וגם בחייו קיים לו ואגדלה שמך והיה ברכה ואשתו מתה ונקברה בנחלת ה' ועוד כי רצה להודיענו מקום קבורת האבות באשר אנחנו חייבים לכבד מקום קבורת אבותינו הקדושים ורבותינו אמרו (ב"ב טז) שגם זה מן הנסיונות של אברהם שבקש מקום לקבור את שרה ולא מצא עד שקנה אותו ולא ידעתי טעם לדברי רבי אברהם שאומר להודיע מעלת ארץ ישראל לחיים ולמתים ועוד לקיים לו דבר השם להיות לו נחלה כי מה מעלה לארץ בזה כי לא יוליכנה אל ארץ אחרת לקברה ודבר השם לאברהם על כל הארץ היה ונתקיים רק בזרעו
@21 **ואברהם זקן בא בימים** . חזר הכתוב לאמר כן להודיע הסבה שבעבורה השביע את עבדו ואמר כי ראה עצמו זקן מאד וחשב בלבו שאם ישלח לארץ מולדתו אולי טרם יחזור השליח ילך לו אל בית עולמו ולכן השביע את עבדו אשר ילך יצחק אחרי עצתו כי הוא המושל בכל אשר לו שלא יקח לו אשה מבנות כנען ובבראשית רבה (נט ו) אמרו כאן זקנה שיש בה לכלוכית ולהלן זקנה שאין בה לכלוכית ירצו לפרש כי "באים בימים" מתחילים בימי הזקנה כי "באים" מורה על זמן עומד כמו הבאים בשערים האלה (ירמיהו ז ב) וכאן אמר שהיה זקן מאד שכבר בא בימים כמו בא אחיך במרמה (להלן כז לה)
@21 "ברך את אברהם בכל" - בעושר ונכסים וכבוד אורך ימים ובנים וזאת כל חמדת האדם (אבן עזרא) והזכיר הכתוב זה לאמר כי היה שלם בכל לא חסר דבר זולתי שיראה בנים לבנו שינחלו מעלתו וכבודו ולכן התאוה לזה ולרבותינו בזה ענין נפלא אמרו (ב"ב טז) וה' ברך את אברהם בכל רבי מאיר אומר שלא היתה לו בת רבי יהודה אומר בת היתה לו אחרים אומרים בת היתה לו ובכל שמה דרש רבי מאיר שלא היתה לו בת לאברהם וזו לו לברכה כי לא היה יכול להשיאה רק לבני כנען הארורים ואם ישלחנה לארצו גם כן תעבוד שם עבודה זרה כמותם כי האשה ברשות בעלה ואברהם לא יחפוץ שיצא זרעו הכשר משרה אשתו חוצה לארץ ואף כי יעבוד עבודה זרה ורבי יהודה דרש כי בת היתה לו דאפילו ברתא לא חסריה רחמנא (שם קמא) והיא הברכה בכל כי היה לו כל אשר יחמדו האנשים לא חסר דבר ובאו אחרים והזכירו שם הבת ובאמת שאין הכוונה לאחרים והמחלוקת להם עם רבי יהודה להודיע אותנו שם הבת הזאת בלבד וחלילה להם שיוציאו ברכתו של אברהם שהיא גדולה וכללית לענין זה שיאמר הכתוב כי ברך אתו השם בבת אחת ששמה כך אבל אחרים חדשו בפירוש הכתוב הזה ענין עמוק מאד ודרשו בזה סוד מסודות התורה ואמרו כי "בכל" תרמוז על ענין גדול והוא שיש להקב"ה מדה תקרא "כל" מפני שהיא יסוד הכל ובה נאמר (ישעיהו מד כד) אנכי ה' עושה כל והוא שנאמר (קהלת ה ח) ויתרון ארץ בכל הוא יאמר כי יתרון הארץ וטובה הגדולה השופע על כל באי עולם בעבור כי בכל היא והיא המדה השמינית מי"ג מדות ומדה אחרת תקרא בת נאצלת ממנה ובה הוא מנהיג את הכל והיא בית דינו של הקב"ה הנרמז במלת וה' בכל מקום (ב"ר נא ב) והיא שנקראת כלה בספר שיר השירים בעבור שהיא כלולה מן הכל והיא שחכמים מכנים שמה כנסת ישראל במקומות רבים בעבור שהיא כנוסת הכל והמדה הזאת היתה לאברהם כבת כי הוא איש החסד ויתנהג בזו ולכך אמרו אחרים כי אין הברכה הזאת שנתברך בכל רומזת על שהוליד בת משרה אשתו או שלא הוליד אבל היא רומזת ענין גדול שברך אותו במדה שהיא בתוך מדת הכל ולכן תקרא גם היא כל כלשון כי שמי בקרבו (שמות כג כא) והנה הוא מבורך בשמים ובארץ ולכך אמר בה' אלהי השמים ואלהי הארץ והענין הזה נמצא לרבותינו רמוז בהגדות במקומות רבים כענין שאמרו במדרש חזית (שיר השירים ג כא) שאל רבי שמעון בן יוחאי את רבי אליעזר ברבי יוסי אפשר ששמעת מאביך מהו בעטרה שעטרה לו אמו (שיר השירים ג יא) אמר לו הן אמר לו היאך אמר לו משל למלך שהיתה לו בת יחידה והיה מחבבה יותר מדאי והיה קורא אותה בתי לא זז מחבבה עד שקרא אותה אחותי ולא זז מחבבה עד שקרא אותה אמי כך בתחילה חבב הקב"ה את ישראל וקראן בתי הדא הוא דכתיב (תהלים מה יא) שמעי בת וראי ולא זז מחבבן עד שקראן אחותי שנאמר (שיר השירים ה ב) פתחי לי אחותי רעיתי ולא זז מחבבן עד שקראן אמי שנאמר (ישעיהו נא ד) הקשיבו אלי עמי ולאומי לאמי כתיב עמד רבי שמעון בן יוחאי ונשקו על ראשו אמר לו אילו לא באתי אלא לשמוע זה הדבר מפיך די ומבואר זה במדרשו של ר' נחוניא בן הקנה (ספר הבהיר כב) אמרו בפסוק אנכי ה' עושה כל נוטה שמים לבדי רוקע הארץ מאתי (ישעיהו מד כד) אני כשנטעתי אילן זה להשתעשע בו כל העולם ורקעתי בו הכל וקראתי שמו כל שהכל תלוי בו והכל ממנו יוצא והכל צריכין לו ובו צופין ולו מחכים ומשם פורחים נשמות לבדי הייתי כשעשיתי אותו ולא יגדל עליו מלאך לאמר אני קדמתי לך גם בעת שרקעתי ארצי שבה נטעתי ושרשתי אילן זה ושמחתים ביחד ושמחתי בהם מי אתי שגליתי לו סודי זה עד כאן ועוד שם מבואר מאי ברוגז רחם תזכור (חבקוק ג ב) אמר בעת שחטאו לך בניך ותכעס עליהם רחם תזכור ומאי רחם תזכור זכור אותו שאמר ארחמך ה' חזקי (תהלים יח ב) ונתת לו המדה הזאת שהיא שכינתן של ישראל וזכור בנו שירשה ונתת לו המדה הזאת שהיא שכינתו של ישראל דכתיב (מלכים א ה כו) וה' נתן חכמה לשלמה וזכור אביהם אברהם דכתיב זרע אברהם אוהבי (ישעיהו מא ח) ובקרב שנים תודיע (חבקוק ג ב) ומהיכן היתה בת לאברהם הן דכתיב וה' ברך את אברהם בכל וכתיב (ישעיהו מג ז) כל הנקרא בשמי ולכבודי בראתיו ההיא ברכה היתה בתו או לא היתה אלא אמו הן בתו היתה משל לאדון שהיה לו עבד שלם תמים לפניו ונסהו בכמה נסיונות ועמד בכולן אמר האדון מה אתן לעבד זה או מה אעשה לו אלא אצונו לאחי הגדול ליעצו ולשמרו ולכבדו חזר העבד עם אחיו הגדול ולמד מדותיו אהבו האח וקראו אוהבי דכתיב זרע אברהם אוהבי אמר מה אתן לו או מה אעשה לו הנה כלי נאה עשיתי ובו מרגליות נאות ואין כמותן והם סגולת מלכים אתננה לו ויזכה במקומי הדא הוא דכתיב וה' ברך את אברהם בכל עד כאן ואם תבין מה שכתבתי תדע מאמר הנשים הארורות שאמרו ומן אז חדלנו לקטר למלכת השמים חסרנו כל (ירמיהו מד יח) ולמה נכתבה המלה חסרת האל"ף ותשכיל דברים רבים סתומים בתורה ומקרא ואילו ידע זה המתהדר בסודותיו תאלמנה שפתיו מהלעיג על דברי רבותינו ולכן כתבתי זה לסכור פי הדוברים על הצדיקים עתק
@23 **ואשביעך בה'** . היה ראוי לאברהם שיצוה את יצחק בנו שלא יקח אשה מבנות כנען אבל היה רצונו לשלוח בחייו אל ארצו ומשפחתו והשביע העבד לעשות כן בחייו או במותו ולכן הוצרך על כל פנים להשביע לעבד ללכת שם והוצרך לאמר אני מצוך שלא תקח אשה לבני מבנות כנען ושתלך אל ארצי ותקח לו אשה מבית אביוכיון שהשביע את העבד על זה לא הוצרך לצוות את יצחק דבר כי יודע בו שלא יעבור על רצון אביו ועל השבועה שהשביע את עבדו כי היה הענין נודע ליצחק באמת גם יתכן שהיה העבד אפוטרופוס על נכסיו וצוה אותו שישיא יצחק לרצונו וינחיל אותו נכסיו על מנת כן וזה טעם המושל בכל אשר לו אלהי השמים ואלהי הארץ הקב"ה יקרא אלהי ארץ ישראל כדכתיב (מלכים ב יז כו) לא ידעו את משפט אלהי הארץ וכתוב (דהי"ב לב יט) וידברו אל אלהי ירושלים כעל אלהי עמי הארץ ויש בזה סוד עוד אכתבנו בעזרת השם (עיין ויקרא יח כה) אבל בפסוק (ז) לקחני מבית אבי לא נאמר בו אלהי הארץ כי היה בחרן או באור כשדים וכן אמרו (כתובות קי) הדר בחוצה לארץ דומה כמי שאין לו אלוה שנאמר (שמואל א כו יט) כי גרשוני היום מהסתפח בנחלת ה' לאמר לך עבוד אלהים אחרים
@25 **וטעם אולי לא תאבה האשה** . האשה אשר אדבר בה מכל הנשים אשר שם או הראויה ליצחק
@27 **מבית אבי ומארץ מולדתי** . לשון רש"י מבית אבי מחרן ומארץ מולדתי מאור כשדים אם כן "אל ארצי ואל מולדתי תלך" יהיה אור כשדים וחלילה חלילה שיתערב זרע הקדש בבני חם הפושע אולי יאמר שהיה לו משפחה שם מזרעו של שם אבל העבד לחרן הלך כאשר דבר אדניו ואולי יחשוב הרב כי ארץ מולדתו אור כשדים אבל "מולדתי" היא משפחתי ו"ארצי" ארץ אשר גר בה וכל אלה דברים בטלים כי בכאן אמר ולקחת אשה לבני משם ועוד כי ימים רבים עמד בארץ כנען יותר מחרן ולמה תקרא חרן ארצו בעבור שגר בה ימים אבל "אל ארצי ואל מולדתי" ארצי ששם מולדתי כי שם עמד ומשם היו אבותיו מעולם וכבר נתבאר (לעיל יא כח יב א) ובבראשית רבה (נט י) מבית אבי זו ביתו של אביו ומארץ מולדתי זו שכונתי ויתכן שיהיה טעם "אל ארצי ואל מולדתי" ארצי ומשפחתי כי גם באנשי ארצו לא יחפוץ רק במשפחתו וכן ולקחת אשה לבני משם רמז אל "מבית אבי" וכן יאמר העבד (להלן פסוק מ) ולקחת אשה לבני ממשפחתי ומבית אבי ואמר (שם מא) כי תבא אל משפחתי או שהיה העבד אומר כן לכבדם שישמעו לו
@27 "ואשר דבר לי" - לשון רש"י לצרכי כמו עלי וכן כל לי ולו ולהם הסמוכים אצל דבור מפורשים בלשון על שאין נופל בלשון דבור אלא אלי אליו אליהם ותרגומם עמי עמיה עמהון אבל אצל אמירה נופל לי ולו ולהם ובפרשת ויצא יעקב הביא ראיה ממה שכתוב שם (להלן כח טו) את אשר דברתי לך שהרי עם יעקב לא דבר קודם לכן ואין החילוק הזה אמת כי הנה מצאנו (שמות לב לד) ועתה לך נחה את העם אל אשר דברתי לך וידברו הכשדים למלך ארמית (דניאל ב ד) והורשתם והאבדתם מהר כאשר דבר ה' אלהיך לך (דברים ט ג) וכן האמירה בשניהם (שמות ג יג) ואמרו לי מה שמו מה אומר אליהם ו "את אשר דברתי לך" פירושו שאמרתי לך עתה שאתן לך את הארץ ולזרעך ואברך אותך
@28 **ונקית משבועתי זאת** . לא הרשה אותו לקחת לו אשה מבנות כנען אבל שיהיה הוא פטור וה' הטוב בעיניו יעשה ורש"י כתב וקח לו אשה מבנות ענר אשכול וממרא ואם כנענים הם חלילה לו ובאמת שהם מזרע כנען שהכתוב אומר (לעיל יד יג) ממרא האמורי אחי אשכול ואחי ענר ובבראשית רבה (נט ח) אמרו אשר לא תקח אשה וגו' הזהירו בבנות כנען ענר אשכול וממרא כי עליהם אמר "אשר אנכי יושב בקרבו" כי הוא לא היה יושב בכל הכנעני כי עמים רבים היו אבל הזהיר על אלה בעלי בריתו וכל שכן על האחרים אבל ונקית משבועתי שיהיה הוא פטור ואברהם הוא היודע ביצחק הצדיק שישמע לאביו ושיזהר בהם וילך לו אל ישמעאל או ללוט ויתר העמים ויתכן כי "משבועתי זאת" רמז למה שאמר ולקחת אשה לבני משם כי אולי היתה השבועה על הכל ולא ירמוז לאשר אמר לו לא תקח אשה לבני מבנות הכנעני וזה טעם "זאת" ולכך אמר העבד ואפנה על ימין או על שמאל (להלן פסוק מט) ולא אמר "אשובה לי"
@30 **וכל טוב אדוניו בידו** . לשון רש"י שטר מתנה שכתב לו כל אשר לו כדי שיקפצו לשלוח לו בתם וכן בבראשית רבה (נט יא) דייתיקי ולדעת זו מה שכתוב (להלן כה ה) ויתן אברהם את כל אשר לו ליצחק לומר שהחזיק אותו בנכסים בשעת פטירתו שלא יערערו בו כמו שאמר וישלחם מעל יצחק בנו בעודנו חי ואם כן תהיה מלת הלקיחה מושכת "וכל טוב אדוניו בידו" לקח בידו או ויקח העבד עשרה גמלים וכל טוב אדוניו בידו וילך ואחרים מפרשים כי העבד כאשר נשבע מיד הלך מעצמו ולקח עשרה גמלים מגמלי אדוניו כי כל טוב אדוניו היה בידו והוא פקיד ונגיד על הכל לקחת ממנו כאשר ירצה כמו שאמר (לעיל פסוק ב) המושל בכל אשר לו והנכון בעיני כי טעם הפסוק הזה כטעם הכתוב בחזאל (מלכים ב ח ט) וילך חזאל לקראתו ויקח מנחה בידו וכל טוב דמשק משא ארבעים גמל אף כאן אמר כי לקח כל טוב אדוניו בידו משא עשרה גמלים והענין כי כל הטוב והמעולה במינים ההם פירות ומגדנות מכל הנמצא בדמשק או בבית אדוניו לקחו משא הגמלים והוליכו מנחה בידם וכן (להלן מה כג) עשרה חמורים נושאים מטוב מצרים והמקראות יקצרו לשונם במובן
@34 **אותה הוכחת לעבדך ליצחק** . לשון רש"י ראויה היא לו שהיא גומלת חסדים וראויה ליכנס בביתו של אברהם ובה אדע לשון תחינה הודיעני בה שעשית חסד עם אדוני ואם כן יאמר ידעתי כי באמת אותה הוכחת לעבדך ליצחק ואינו נקשר יפה אבל פירושו הקרה נא לפני היום הזה המקרה שתהיה הנערה אשר אומר אליה אותה שהוכחת לעבדך ליצחק ועשה בזה חסד עם אדוני אברהם כי בה אדע כי עשית חסד עמו אם תהיה ממשפחתו וטובת שכל ויפת מראה וכן אמר (להלן פסוק מג) והיה העלמה היא האשה אשר הוכיח ה'
@35 **אשר ילדה לבתואל בן מלכה** . בעבור שהיה לנחור בנים מפלגשו ראומה ייחסו לעולם בתואל בן מלכה ובעבור שהנערה הזכירה אם אביה תחלה בת בתואל אנכי בן מלכה כי כן דרך הנערות כדרך ותגד לבית אמה (להלן פסוק כח) לכן יזכירנו הכתוב כי הוא בן מלכה אשת נחור אבל העבד אמר ותאמר בת בתואל בן נחור (שם מז) כי תיקן הדבר בדרך מוסר אבל אמר אשר ילדה לו מלכה לומר שהוא בן הגבירה
@37 **וירץ העבד לקראתה** . לשון רש"י לפי שראה שעלו המים לקראתה ובבראשית רבה (ס ה) ותמלא כדה ותעל כל הנשים יורדות וממלאות מן העין וזו כיון שראו אותה המים מיד עלו אמר לה הקב"ה את סימן ברכה לבניך נראה שדקדקו כן מלשון ותמלא כדה ותעל שלא אמר "ותשאב ותמלא" ונעשה לה הנס בפעם הראשונה כי אחרי כן כתוב "ותשאב" והעבד כשספר להם אמר (להלן פסוק מה) ותרד העינה ותשאב אולי לא יאמינו
@42 **ויקח האיש נזם זהב ושני צמידים על ידיה** . הכתוב הזה יחסר המעשה שהיה צריך שיאמר "ויקח האיש נזם זהב ויתן על אפה ושני צמידים על ידיה" ולכך אני אומר כי פירושו ויקח האיש נזם זהב ושני צמידים שיהיו על ידיה ויאמר לה בת מי את ואחרי שאמרה אליו "בת בתואל אנכי" שם הנזם על אפה והצמידים על ידיה כאשר אמר להם אבל חסר כאן הנתינה וכן במקומות רבים
@52 **ויבא האיש הביתה** . אליעזר הוא האיש הבא ויפתח הגמלים יחזור על לבן שעשה עם אורחיו דרך מוסר ויפתח גמליהם ויתן להם תבן ומספוא ונתן מים לרחוץ רגלי אליעזר ורגלי האנשים אשר אתו כי רחוק הוא שיהיה אליעזר הוא הנותן מים לרחוץ רגליו ורגלי אנשיו וכן ויעברו אנשים מדינים סוחרים וימשכו ויעלו את יוסף מן הבור (להלן לז כח) כי "וימשכו" חוזר אל אחיו הנזכרים בפסוק הראשון וכן ויאמר ציבא אל המלך ככל אשר יצוה אדוני המלך את עבדו כן יעשה עבדך ומפיבושת אוכל על שולחני כאחד מבני המלך ( ט יא) והם דברי דוד ורבים כן וענין ויפתח הגמלים שפתח מוסרי צוארם כי המנהג להוליכם קשורים או שהיו הולכים חגורים במושב המרכבה אשר עליהם כלשון אל יתהלל חוגר כמפתח (מלכים א כ יא) התפתחי מוסרי צוארך (ישעיהו נב ב) ורש"י כתב התיר זמם שלהם שהיה סותם פיהם שלא ירעו בשדות אחרים ולשון בראשית רבה (ס ח) התיר זממיהם רבי הונא ורבי ירמיה שאל לרבי חייא ברבי אבא לא היו גמליו של אברהם אבינו דומים לחמורו של רבי פנחס בן יאיר וכו' וזו שאלה לסתור פתוח הזמם כי אי אפשר שיהיה החסידות בביתו של רבי פנחס בן יאיר גדול יותר מביתו של אברהם אבינו וכאשר חמורו של רבי פנחס בן יאיר איננו צריך להשתמר מן הדברים האסורים לבעליו להאכילו כל שכן גמליו של אברהם אבינו ואין צריך לזממם כי לא יאונה לצדיק כל און
@65 **וטעם והנה רבקה יצאת וכדה על שכמה** . כי בהיותו בביתה שמע את שמה או מתחילה הגידה לו שמה אע"פ שלא נזכר
@81 **ותקם רבקה ונערותיה** . סיפר הכתוב כי אחר שנתנו רשות שתלך רבקה ומיניקתה ועבד אברהם ואנשיו קמה רבקה וקראה נערותיה ותרכבנה על הגמלים ותלכנה אחרי האיש כי הוא מורה הדרך לפניהם וטעם ויקח העבד את רבקה וילך לספר בזריזותו כי אחרי צאתו מן העיר ותלכנה כל הנשים אחריו לקח העבד את רבקה עמו לא יפרד ממנה לשומרה בדרך מכל מכשול ורבי אברהם אמר כי טעמו שהיה הולך עם רבקה ולא הרגיש עד שבא יצחק ופגע בו
@82 **בא מבוא באר לחי ראי** . יאמר כי יצחק בא עתה מבוא באר לחי ראי ששב מבאר לחי שבא שמה שאלו אמר "בא מבאר לחי ראי" היה נראה שהיה דר שם ולכך הוצרך לפרש כי הוא שב לעירו מביאתו שבא אל באר לחי רואי לפי שעה כי הוא יושב בארץ הנגב וחוזר לעירו ויתכן בעבור היות "מבוא" מקור שהיה יצחק הולך תמיד אל המקום ההוא כי הוא לו מקום תפלה בעבור הראות שם המלאך והוא יושב בארץ הנגב קרוב משם וכן תרגם אונקלוס אתא ממיתוהי ועל דעתו הוא באר שבע שתרגם "בין קדש ובין שור" (לעיל כ א) ו"בין קדש ובין ברד" (לעיל טז יד) "רקם וחגרא" ואם כן המקום ההוא מקום אשל אברהם ראוי לתפלה והנה יצחק בא מן הבאר ההיא אל עיר אחרת אשר היתה בדרך עירו ויצא לפנות ערב לשוח בשדה עם רעיו ואוהביו אשר שם ומצא את העבד ורבקה והלכו כלם יחדו אל עירו ויביאה האהלה שרה אמו
@84 **ותרא את יצחק** . לשון רש"י ראתה אותו הדור ונתביישה ממנו ורבי אברהם פירש כי הפסוק האחרון מוקדם כי "ותאמר אל העבד" וכבר אמרה אל העבד ורבים בתורה כן על דעתו ובאמת שימצאו מהם אבל בכאן איננו נכון שיצטרך לערב שתי המקראות ותשא רבקה את עיניה ותרא את יצחק ותאמר אל העבד מי האיש הלזה ההולך בשדה לקראתנו ויאמר העבד הוא אדוני ותפול מעל הגמל ותקח הצעיף ותתכס ולדעתי בראות רבקה איש הולך לקראתה בשדה שירט הדרך והלך בשדה לעומתם ידעה כי הוא בא לראותם ולקרוא לשלום או להכניסם אל ביתו ללון עשתה כדרך מוסר הנשים לעמוד בהצנע
@84 "ותפול מעל הגמל" - לשון רש"י השמיטה עצמה לארץ כתרגומו ואתרכינת כמו הטי נא כדך (לעיל פסוק יד) ארכיני ויט שמים וירד (תהלים יח י) וארכין ודומה לו כי יפול לא יוטל (שם לז כד) אם יטה לארץ לא יגיע לקרקע ואין דעת אונקלוס שהשמיטה עצמה מן הגמל לארץ שאם כן הנה היא נופלת מעל הגמל ממש לא מוטה מעליו וכן כל לשון "הרכנה" הטיה לצד אחד בלבד אבל כוונתו כי מעל הגמל אשר היא רוכבת עליו הטת עצמה לצד אחד להסב פניה ממנו וכמוהו לדעתי ויראה נעמן רץ אחריו ויפול מעל המרכבה לקראתו ויאמר השלום (מלכים ב ה כא) שאין ענינו רק שהשפיל עצמו במרכבה לקראת הרץ אשר היה בארץ לשאול לו בשלום וכן אמר (שם כו) כאשר הפך איש מעל מרכבתו לקראתך או יהיה אצל אונקלוס "מעל הגמל" כמו "על הגמל" וכן מעל שמים חסדך (תהלים קח ה) וכזו המ"ם לא יהיה משם עוד עול ימים וזקן (ישעיהו סה כ) וכן המים אשר מעל השמים (תהלים קמח ד) ועל דרך הפשט הוא כמו והנה עם רב הולכים מדרך אחריו ( יג לד) וכן רבים
@87 **ויביאה יצחק האהלה שרה אמו** . חסר הנסמך וכמוהו רבים וטעם הכתוב כי יספר בכבוד שנהג יצחק באמו כי מעת שמתה שרה לא נטו אהלה כי אמרו לא תבא אשה אחרת אל אהל הגבירה הנכבדת וכאשר ראה רבקה הביאה אל האהל ההוא לכבודה ושם לקחה וזה טעם ויאהבה וינחם ירמוז שהיה מצטער מאד על אמו ורחק ממנו מנחם עד שנחם באשתו באהבתו אותה כי מה טעם שיזכיר הכתוב אהבת האיש באשתו ואונקלוס פירש ויביאה יצחק האהלה והנה היא שרה אמו ולכן הזכיר האהבה כי מפני צדקתה וכשרון מעשיה אהבה ונחם בה וכך הזכירו בבראשית רבה (ס טז) עד שלא מתה שרה היתה ברכה מצויה בעיסה
@90 **אשורים ולטושים ולאומים** . לשון רש"י שהם ראשי אומות ותרגומו של אונקלוס אין לישבו עם לשון המקרא ולי נראה שסבר אונקלוס ב"אשורים" שהם המחנות שיירות הולכי דרך מעיר לעיר כמו שאמר אורחת ישמעאלים (להלן לז כה) עשאו מלשון באשורו אחזה רגלי (איוב כג יא) לא תמעד אשוריו (תהלים לז לא) וסבר ב"לטושים" שהם השוכנים באהלים שהם נטושים על פני האדמה היום ישכנו במקום ההוא ולמחר במקום אחר כי הלמ"ד והנו"ן יומרו במקומות רבים כמו לשכה ונשכה ויפקדו ביום ההוא אנשים על הנשכות (נחמיה יב מד) ומזה חרב נטושה (ישעיהו כא טו) כמו לטושה ואמר ב"לאומים" "ולנגון" בלשון איים ומלת "היו" עוררה אותו בזה שהיה ראוי שיאמר כמו שאמר (לעיל י יג) ומצרים ילד את לודים ואת ענמים ואת להבים ואת נפתוחים ובבראשית רבה (סא ה) רבי שמואל בר רב נחמן אמר אף על גב דאנן מתרגמינן ואמרין תגרין ולפדין וראשי אומים כלם ראשי אומות הן והענין כמו שפירשתי כי היו המתרגמין עושים אשורים תגרין הולכי דרך והיו עושין מן לטושים אנשי רשע פניהם פני להבים בוערים כלפידים מן ללטוש את מחרשתו ואת אתו (שמואל א יג כ) ילטוש עיניו לי (איוב טז ט) ואמר רבי שמואל בר רב נחמן שאף על פי שנהגו לתרגם כן אינם אלא ראשי אומות אין בהם שם תואר כלל וכך הדבר
@93 **ולבני הפילגשים אשר לאברהם** . על דרך הפשט בעבור שנאמר לו (לעיל כא יב) כי ביצחק יקרא לך זרע לא בזרע אחר היו כל נשיו אצלו פילגשים לא היו נחשבות לנשים שאין זרען ביורשיו כי הגר שפחת שרה פילגשו היתה אבל קטורה לאשה לקח לו ואם היתה שפחה בביתו ולקחה לפילגש לא היה אומר "ויקח אשה ושמה קטורה" רק תקרא פילגש בכתוב מפני הטעם שפירשתי ובדברי הימים (א א לב) כתוב ובני קטורה פילגש אברהם והנה אברהם לקח לו אשה מבנות כנען ואם תאמר שהיתה מצרית או מארץ פלשתים הנה לא שלח אל ארצו ואל מולדתו כאשר עשה בבנו כי איננו שומר רק זרע יצחק כי עליו נכרת הברית ועוד שלא אמר הכתוב "ויקח אשה קטורה בת פלוני החוי או הפלשתי והמצרי מארץ פלונית" כאשר אמר בנשי עשו (להלן כו לד) וזולתן אבל הזכיר שמה בלבד כי היא כנענית וקצר ביחוסה וכן יעשה במקומות רבים כשלא יקפיד בייחוס שלהן ואולי תקרא פילגש בעבור היותה שפחה ממשפחת העבדים ואם היתה שפחה בביתו ובא אליה לא יזכיר ייחוסה כי אין דרך הכתוב להזכיר באמהות רק שמן כענין בזלפה ובלהה ורש"י כתב נשים בכתובה פילגשים שלא בכתובה כדאמר בנשים ופילגשים דדוד בסנהדרין (כא) ואין הדבר כן כי לא תקרא פילגש אלא כשהיא בלא קדושין כי הכתובה מדברי סופרים והגירסא בסנהדרין פילגש בלא כתובה וקדושין אבל אפשר שגם בני נח כאשר ישאו להם נשים כמשפטן בבעילה היו נוהגים לכתוב להן מהר ומתן ואשר רצונה שתהיה להם פילגש וישלח אותה כאשר ירצה ולא יהיו בניה בנוחלים את שלו לא היה כותב לה כלום ועל דעת רבותינו (ב"ר סא ד) שהיא הגר הנה היא פילגש ודאי
@95 **זקן ושבע** . שראה כל משאלות לבו ושבע כל טובה וכן ושבע ימים (להלן לה כט) ששבעה נפשו בימים ולא יתאוה שיחדשו בו הימים דבר וכענין שנאמר בדוד וימת בשיבה טובה שבע ימים ועושר וכבוד (דהי"א כט כח) והוא ספור חסדי השם בצדיקים ומדה טובה בהם שלא יתאוו במותרות כענין שנאמר בהם תאות לבו נתת לו (תהלים כא ג) ולא כמו שנאמר בשאר האנשים אוהב כסף לא ישבע כסף (קהלת ה ט) ואמרו בו (קהלת רבה א יג) אין אדם יוצא מן העולם וחצי תאוותיו בידו יש בידו מנה מתאוה מאתים השיגה ידו למאתים מתאוה לעשות ארבע מאות שנאמר אוהב כסף לא ישבע כסף ובבראשית רבה (סב ב) אמרו הקב"ה מראה להם לצדיקים מתן שכרן שהוא עתיד ליתן להם לעולם הבא ונפשם שבעה והם ישנים נתעוררו החכמים בזה ופירשו הכתוב שאומר "ושבע" במראה הזו
@96 **ויקברו אותו יצחק וישמעאל בניו** . לשון בראשית רבה (סב ג) כאן בן האמה חולק כבוד לבן הגבירה
@98 **וישב יצחק עם באר לחי ראי** . קרוב אל המקום ההוא או בעבור שאיננו עיר אמר כי נטה אהלו אצל הבאר
@104 **ואלה שני חיי ישמעאל** . הקרוב בדרך הפשט כי הכתוב יספר בבני הצדיקים תולדותם ומספר חייהם להודיע כי זרע צדיקים יבורך ולא ספר ימי עשו כי חיה יותר מיעקב וכבר נשלם הספור במות יעקב ולא רצה לחזור אלה חיי עשו שכבר הזכיר תולדותיו במקום הראוי להם ובמדרש רבותינו בסיפור ימי ישמעאל טעמים רבים (עיין מגילה יז) והנכון שבהם שהיה צדיק בעל תשובה וסיפר בו כדרך הצדיקים
@104 "ויגוע" - לשון רש"י לא נאמרה גויעה אלא בצדיקים ובגמרא (ב"ב טז) הקשו והא דור המבול נאמר בהם גויעה ויגוע כל בשר הרומש על הארץ וגו' וכל האדם (לעיל ז כא) כל אשר בארץ יגוע (לעיל ו יז) ומתרץ גויעה ואסיפה קאמרינן כוונתם כי הגויעה מיתה בלא חולי מכאיב ובלא יסורין ואין זוכין לה אלא הצדיקים ואנשי דור המבול ההפוכים כמו רגע ולא חלו בהם ידים וכן מתי מדבר ועל כן אמר בהם גויעה בגוע אחינו (במדבר כ ג) וכן והוא איש אחד לא גוע בעונו (יהושע כב כ) שלא המית אותו עונו פתאום אבל כשיזכיר הכתוב כן עם זכרון המיתה כמלת ויאסף או וימת תרמוז למיתת הצדיקים ולשון בראשית רבה (סב ב) ויגוע וימת אברהם (לעיל פסוק ח) אמר רבי יהודה בר אילעי החסידים הראשונים היו מתיסרין בחולי מעים בעשרה ובעשרים יום לומר שהחולי ממרק רבי יהודה אומר כל מי שנאמרה בו גויעה מת בחולי מעים ושם (לעיל ו יז) אמרו וכל אשר בארץ יגוע יצמוק ויראה שמלת גויעה אצלם המק בשרו והוא עומד על רגליו (זכריה יד יב) וכן דעת אונקלוס שתרגם בכאן ואתנגיד והוא העלוף כלשון אתנגיד ואתפח (סנהדרין לט) יכול ישלם חמשה נגידים (ב"ק סז) ונאמר כן במבול כמו שאמר (לעיל ז כג) וימח את כל היקום ונאמר ויגוע וימת כגבר יחלש וימות והיא מיתה בצדיקים חסלת פרשת חיי שרה
